arguments.command:
cd /testbed && python -c "
import os
for root, dirs, files in os.walk('tests/files'):
    for f in files:
        if f.endswith('.dbc') or f.endswith('.kcd') or f.endswith('.sym'):
            path = os.path.join(root, f)
            with open(path, 'rb') as file:
                content = file.read()
                if b'\xef\xbc\x9f' in content:
                    print(f'Found fullwidth underscore in: {path}')
"

cd /testbed && python -c "
import os
fullwidth_count = 0
for root, dirs, files in os.walk('tests/files'):
    for f in files:
        path = os.path.join(root, f)
        try:
            with open(path, 'rb') as file:
                content = file.read()
                if b'\xef\xbc\xbf' in content:
                    fullwidth_count += 1
                    print(f'Found fullwidth underscore in: {path}')
        except:
            pass
print(f'Total files with fullwidth underscore: {fullwidth_count}')
"

